add("理科", 3, "成熟的红细胞有细胞核吗？", "没有", "有", "有两个", "有，但很小", "哺乳动物成熟的红细胞会丢掉细胞核，腾出空间多装血红蛋白，专心运氧。原来红细胞是“无核”的快递员。");
add("理科", 3, "O型血为什么被称为“万能供血者”？", "红细胞表面没有A、B抗原", "O型血的人最多", "O型血最干净", "O型血凝固最快", "O型红细胞表面没有A、B抗原，输给别人不容易引起排斥。但O型血的人只能接受O型血。原来“万能”是单向的。");
add("理科", 3, "大熊猫的“第六根手指”其实是什么？", "腕骨变来的“伪拇指”", "真的第六根手指", "多长的一根竹子", "退化的尾巴", "熊猫手腕上的一块籽骨变大变长，像拇指一样帮它握住竹子。原来熊猫是“自己动手”长了个“拇指”出来。");
add("理科", 3, "小丑鱼和海葵是什么关系？", "共生互助", "捕食关系", "寄生关系", "竞争关系", "小丑鱼住在海葵的触手里求保护，帮海葵赶走小虫、带来食物，双赢。原来《海底总动员》里的尼莫住的是“保镖家”。");
add("理科", 3, "竹节虫长得像树枝，这是哪种生存策略？", "拟态", "攻击", "迁徙", "冬眠", "竹节虫把自己伪装成树枝或树叶，让天敌看不见，这叫拟态。有的还能装死、释放臭气。原来“隐身术”在昆虫界很流行。");
add("理科", 3, "电鳗放电主要靠身体的哪种结构？", "特化的肌肉细胞", "大脑", "心脏", "鳞片", "电鳗身体两侧有成千上万个特化的肌肉细胞，像小电池一样串联起来，一次能放出几百伏电压。原来电鳗是“行走的发电机”。");
add("理科", 3, "候鸟长途迁徙主要靠什么辨认方向？", "地球磁场", "看太阳的位置", "闻气味", "跟着头雁飞", "很多候鸟能感知地磁场，像带着指南针，阴天也能飞。科学家还在它们眼睛里找到了感磁蛋白。原来鸟的眼睛能“看见”磁场。");
add("理科", 3, "把一个人体细胞里的DNA全部拉直，大约有多长？", "约2米", "约2厘米", "约20厘米", "约200米", "一个细胞的DNA展开约2米长，全靠精密折叠才塞进微米级的细胞核。原来每个细胞里都盘着“两米长的线”。");
add("理科", 3, "线粒体在细胞里主要负责什么？", "提供能量", "控制遗传", "合成蛋白质", "消化食物", "线粒体把葡萄糖转化成细胞能用的能量，是细胞的“发电厂”。它还有自己的DNA，据说是远古细菌“打工”留下的。原来发电厂以前是“外来户”。");
add("理科", 3, "人冷的时候为什么会起鸡皮疙瘩？", "汗毛竖起保暖，是远古留下的反应", "皮肤过敏", "血液循环不好", "缺乏维生素", "立毛肌收缩让汗毛竖起，远古人类毛多时能锁住空气保暖，还能“炸毛”吓唬敌人。现在毛少了，反应还在。原来鸡皮疙瘩是“退役”的保暖系统。");
add("理科", 3, "人的指纹为什么各不相同？", "胎儿期随机形成的纹路", "后天磨出来的", "和血型有关", "和父母一模一样", "指纹在胎儿期由皮肤生长的随机褶皱形成，连同卵双胞胎都不一样。原来指纹是“随机生成的密码”。");
add("理科", 3, "阑尾真的一点用都没有吗？", "并非完全没用，可能是肠道细菌的“避难所”", "完全没用", "会分泌消化液", "是造血器官", "有科学家认为，阑尾是肠道有益菌的“避难所”，腹泻后能帮肠道恢复菌群。原来阑尾可能是“细菌的诺亚方舟”。");
add("理科", 3, "蛇是变温动物还是恒温动物？", "变温动物，体温随环境变化", "恒温动物", "一半一半", "蛇没有体温", "蛇不能自己产热维持体温，靠晒太阳取暖、钻阴凉处降温，所以冬天要冬眠。原来蛇是“太阳能”的。");
add("理科", 3, "大树把根吸收的水分送到上百米的树顶，主要靠什么力量？", "蒸腾拉力", "根部的压力", "风力", "树干收缩", "叶子蒸腾失水，在导管里形成向上的拉力，像无数根吸管把水“拽”上去。原来大树喝水靠的是“叶子出汗”。");
add("理科", 4, "缓步动物（水熊虫）以什么本领出名？", "能在极端环境下存活", "跑得飞快", "力气特别大", "会发光", "水熊虫能耐受真空、强辐射、极高低温和高压，进入隐生状态后几乎“不死”，科学家甚至把它送上过太空。原来地球上最“硬核”的动物只有一毫米。");
add("理科", 4, "灯塔水母为什么被称为“永生”水母？", "能从成年体变回幼年水螅体重新生长", "它永远不会死", "它能活一万年", "它没有天敌", "灯塔水母在受伤或饥饿时，能从水母体逆转回水螅体，理论上可以不断重启生命周期。原来它靠“返老还童”卡了生命的bug。");
add("理科", 4, "螳螂虾的眼睛有什么特别之处？", "能看到偏振光，感光色素种类远超人类", "能看得很远", "夜视能力超强", "能发射激光", "人类只有3种感光色素，螳螂虾有12到16种，还能看见偏振光。原来它眼中的世界比我们“多彩”得多。");
add("理科", 4, "鸭嘴兽有什么让科学家困惑的特点？", "是产卵的哺乳动物", "长着翅膀", "生活在海里", "没有嘴巴", "鸭嘴兽用乳汁哺育后代却是卵生，刚发现时科学家以为是恶作剧拼凑的标本。它还是少数有毒的哺乳动物。原来哺乳动物里也有“下蛋”的。");
add("理科", 4, "CRISPR技术主要用来做什么？", "精确编辑基因", "克隆动物", "制造疫苗", "检测血型", "CRISPR能像剪刀一样精确定位并修改DNA，发明者因此获得2020年诺贝尔化学奖。原来改基因可以像“查找替换”一样精准。");
add("理科", 4, "“寒武纪大爆发”指的是什么事件？", "恐龙灭绝", "火山大爆发", "约5.4亿年前生物种类突然大量出现", "人类出现", "约5.4亿年前，几乎所有动物门类在地质学一瞬间集中出现，之前的化石记录里几乎找不到它们。原来复杂生命是“突然”登场的。");
add("理科", 4, "人的线粒体DNA一般来自父亲还是母亲？", "母亲", "父亲", "父母各一半", "随机", "受精卵的线粒体几乎全来自卵细胞，所以线粒体DNA只走母系遗传，科学家靠它追溯“线粒体夏娃”。原来查“母系祖先”要看线粒体。");
add("理科", 4, "裸鼹鼠有什么特殊的本领？", "几乎不得癌症", "会飞", "能冬眠十年", "刀枪不入", "裸鼹鼠极少得癌症，对酸痛也不敏感，还能在缺氧环境里存活，是科学家研究抗癌和长寿的明星。原来这种“小老头”样子的动物是“抗癌冠军”。");
add("理科", 4, "章鱼适应环境有个独特的“黑科技”是什么？", "能大量编辑自己的RNA", "会隐身", "能发电", "会冬眠", "章鱼能大规模编辑自己的RNA来微调蛋白质功能，快速适应温度变化，编辑量远超其他动物。原来章鱼是“现场改代码”的高手。");
add("理科", 4, "蝾螈失去一条腿后会怎样？", "重新长出一条完整的腿", "装上假肢", "伤口愈合但长不回来", "变成两条腿", "蝾螈能再生出完整的四肢，包括骨头、肌肉和神经，科学家正在研究它的再生机制。原来“断肢重生”不是神话。");
add("理科", 4, "鼓虾的大螯有什么绝招？", "打出巨响的冲击波", "夹断东西", "当盾牌用", "用来挖洞", "鼓虾大螯快速闭合，在水中打出高速水流，形成空化气泡，气泡坍缩时产生巨响和冲击波，能震晕小鱼。原来它是“水下狙击手”。");
add("理科", 4, "朊病毒和普通病毒最大的不同是什么？", "它只有蛋白质，没有核酸", "它个头更大", "它有颜色", "它只感染植物", "朊病毒没有DNA或RNA，只是一团错误折叠的蛋白质，却能“传染”给正常蛋白，引起疯牛病。原来没有基因也能“复制”自己。");
add("理科", 4, "染色体末端的端粒和什么有关？", "细胞衰老", "智商高低", "血型", "性别", "细胞每分裂一次端粒就短一截，短到极限细胞就不再分裂，这和衰老密切相关。原来染色体末端有个“生命倒计时器”。");
add("理科", 4, "人体内的细菌数量和人体细胞数量比起来怎么样？", "数量差不多，甚至更多", "少得多", "多一百倍", "人体内没有细菌", "研究估算，人体携带的细菌和人体细胞数量大体相当，主要住在肠道里，帮我们消化、护肠道。原来人是个“行走的细菌培养皿”。");
add("理科", 4, "深海中很多鱼会自己发光，这种本领在生物学上叫什么？", "生物发光", "反光", "荧光", "磷光", "深海鱼用生物发光来诱饵、求偶、照明，靠的是荧光素和荧光素酶的化学反应。原来在伸手不见五指的深海，鱼是“自带手电筒”的。");

// ───────────── 新增 · 文史 ─────────────
add("文史", 1, "传说中“开天辟地”的是谁？", "盘古", "女娲", "伏羲", "黄帝", "盘古开天辟地，撑开天地后身体化作山川、日月、风云，是中国神话里的创世神。“盘古开天地”的故事流传了上千年。");
add("文史", 1, "“女娲补天”时，女娲用什么补好了天？", "五彩石", "金砖", "木头", "棉花", "传说天塌地陷，女娲炼出五彩石把天补好，又斩下神龟的四只脚撑住四角。从此天不再漏，地不再陷。");
add("文史", 1, "后羿射日，一共射下了几个太阳？", "九个", "一个", "三个", "十个", "天上曾有十个太阳一起出来，把大地烤得龟裂。后羿射下九个留下一个，从此一天只有一个太阳。");
add("文史", 1, "“愚公移山”里，愚公要搬走的是哪两座山？", "太行山和王屋山", "泰山和华山", "黄山和庐山", "长白山和天山", "太行、王屋两座大山挡在愚公家门口，他子子孙孙坚持挖山。天帝被感动，派神仙把山搬走了。");
add("文史", 1, "牛郎和织女每年在什么时候相会？", "七月初七", "正月十五", "八月十五", "九月初九", "七月初七是七夕，喜鹊搭成鹊桥让牛郎织女相会。所以七夕又叫“中国情人节”。");
add("文史", 1, "十二生肖中，排在第一位的是什么动物？", "鼠", "牛", "虎", "龙", "传说动物们赛跑定生肖，老鼠骑在牛背上，终点前轻轻一跃抢了第一。老实的牛排第二。");
add("文史", 1, "“孔融让梨”中，孔融把大梨让给了谁？", "哥哥", "弟弟", "自己", "客人", "小孔融把大梨让给哥哥姐姐，自己拿最小的。他说哥哥比我大，应该吃大的，是尊老爱幼的榜样。");
add("文史", 1, "花木兰替父从军，她女扮男装替的是谁？", "父亲", "哥哥", "丈夫", "儿子", "父亲年老多病，木兰替父从军十二年，屡立战功。班师回朝后她才换回女装，同袍都大吃一惊。");
add("文史", 1, "“司马光砸缸”中，司马光砸缸是为了救谁？", "掉进缸里的小伙伴", "自己", "一只小猫", "一条小鱼", "小伙伴掉进装满水的大缸，众人都慌了。小司马光搬起大石头砸破缸，水流出来，小伙伴得救了。");
add("文史", 1, "中国历史上第一个朝代是哪个？", "夏朝", "商朝", "周朝", "秦朝", "大禹治水成功后建立夏朝，是中国史书记载的第一个王朝。从此“家天下”代替了禅让制。");
add("文史", 1, "万里长城主要是在哪个朝代连成万里的？", "秦朝", "唐朝", "宋朝", "明朝", "秦始皇统一后，把秦、赵、燕等国的旧长城连成万里长城。现在我们看到的长城，多是明朝修建的。");
add("文史", 1, "中国历史上的最后一个封建王朝是哪个？", "清朝", "明朝", "元朝", "唐朝", "1644年清军入关建立全国政权，1912年溥仪退位，清朝灭亡，它是中国最后一个封建王朝。");
add("文史", 1, "古埃及最著名的建筑是什么？", "金字塔", "长城", "斗兽场", "比萨斜塔", "金字塔是古埃及法老的陵墓，最大的胡夫金字塔高146米，用了230万块巨石，是世界七大奇迹之一。");
add("文史", 1, "奥林匹克运动会起源于哪个国家？", "古希腊", "古罗马", "古埃及", "古印度", "奥运会起源于古希腊的奥林匹亚，“奥林匹克”就是这个地名。现代奥运会从1896年开始，每四年一届。");
add("文史", 1, "“电话”是谁发明的？", "贝尔", "爱迪生", "瓦特", "诺贝尔", "1876年贝尔发明电话，并打通了人类第一通电话。爱迪生发明了电灯，瓦特改进了蒸汽机。");
add("文史", 2, "“纸上谈兵”说的是哪位赵国将领？", "赵括", "廉颇", "蔺相如", "白起", "赵括熟读兵书却没打过仗，接替廉颇后大败于秦军。“纸上谈兵”讽刺只会空谈、不懂实践的人。");
add("文史", 2, "“完璧归赵”中，蔺相如带回赵国的宝贝是什么？", "和氏璧", "夜明珠", "传国玉玺", "青铜鼎", "秦国想骗走赵国的和氏璧，蔺相如机智周旋，完好无损地把宝玉带回赵国。和氏璧后来被做成了传国玉玺。");
add("文史", 2, "“丝绸之路”是谁出使西域后开辟的？", "张骞", "班超", "玄奘", "郑和", "汉武帝时张骞两次出使西域，打通了通往中亚的商路。因为主要运送丝绸，被称为“丝绸之路”。");
add("文史", 2, "“鉴真东渡”去的是哪个国家？", "日本", "朝鲜", "琉球", "印度", "唐朝高僧鉴真六次东渡日本，前五次都失败，第六次成功时已经双目失明。他把佛法和中华文化带到日本。");
add("文史", 2, "“虎门销烟”是谁领导的？", "林则徐", "曾国藩", "李鸿章", "左宗棠", "1839年林则徐在虎门把收缴的两万多箱鸦片全部销毁。这一壮举沉重打击了英国殖民者，他被誉为民族英雄。");
add("文史", 2, "“辛亥革命”推翻的是哪个王朝？", "清朝", "明朝", "元朝", "宋朝", "1911年武昌起义爆发，各省纷纷独立，清朝灭亡。辛亥革命结束了中国两千多年的封建帝制。");
add("文史", 2, "“昭君出塞”中，王昭君远嫁的是哪个民族？", "匈奴", "鲜卑", "突厥", "蒙古", "汉元帝时，王昭君远嫁匈奴呼韩邪单于，换来汉匈六十多年和平。“昭君出塞”成为民族团结的佳话。");
add("文史", 2, "“玄武门之变”后，谁当上了唐朝皇帝？", "李世民", "李建成", "李元吉", "李隆基", "626年李世民在玄武门除掉太子李建成和齐王李元吉，不久即位为唐太宗，开创了“贞观之治”。");
add("文史", 2, "“女皇帝”武则天建立的朝代叫什么？", "武周", "唐朝", "宋朝", "明朝", "武则天是中国历史上唯一的女皇帝，她改国号为“周”，史称武周。她在位时延续了唐朝的繁荣。");
add("文史", 2, "“蒙古帝国”的建立者是谁？", "成吉思汗", "忽必烈", "努尔哈赤", "皇太极", "1206年铁木真统一蒙古各部，被尊为成吉思汗，建立蒙古帝国。他的子孙后来建立了横跨欧亚的大帝国。");
add("文史", 2, "“戚继光”抗击的是哪伙敌人？", "倭寇", "沙俄", "英军", "法军", "明朝时日本海盗（倭寇）骚扰东南沿海，戚继光组建“戚家军”，九战九捷，基本肃清了倭患。");
add("文史", 2, "“郑成功”从哪个国家手里收复了台湾？", "荷兰", "英国", "葡萄牙", "西班牙", "1662年郑成功打败盘踞台湾38年的荷兰殖民者，收复台湾。他被后人尊为“民族英雄”。");
add("文史", 2, "“望梅止渴”讲的是谁带兵打仗的故事？", "曹操", "刘备", "孙权", "诸葛亮", "曹操带兵走过没水的地方，士兵口渴难耐。他说前面有大片梅林，士兵想起梅子酸味就不那么渴了，坚持走到了水源。");
add("文史", 2, "“乐不思蜀”的主人公是谁？", "刘禅", "刘备", "孙权", "曹操", "蜀汉灭亡后，刘禅在洛阳安享富贵，被问想不想念蜀国，他说“此间乐，不思蜀”。后人用它讽刺忘本的人。");
add("文史", 2, "“负荆请罪”中，背着荆条请罪的是谁？", "廉颇", "蔺相如", "赵括", "平原君", "大将廉颇不服蔺相如，蔺相如处处退让。廉颇深受感动，背上荆条登门请罪，两人结成“刎颈之交”。");
add("文史", 3, "“破釜沉舟”的主人公是谁？", "项羽", "刘邦", "韩信", "张良", "巨鹿之战中，项羽砸锅沉船，断绝退路，率楚军以少胜多大破秦军。“破釜沉舟”比喻下定决心干到底。");
add("文史", 3, "进咸阳后“约法三章”的是谁？", "刘邦", "项羽", "萧何", "韩信", "刘邦进咸阳后，与百姓约法三章：杀人者死，伤人及盗抵罪。秦人拥护刘邦，为他后来夺取天下打下基础。");
add("文史", 3, "“文景之治”出现在哪个朝代？", "西汉", "东汉", "唐朝", "宋朝", "“文景之治”指汉文帝、汉景帝在位时的盛世，轻徭薄赋、与民休息，为汉武帝的强盛打下了基础。");
add("文史", 3, "“罢黜百家，独尊儒术”是谁提出的？", "董仲舒", "孔子", "朱熹", "王阳明", "汉武帝时董仲舒提出“罢黜百家，独尊儒术”，儒家思想从此成为中国封建社会的正统思想。");
add("文史", 3, "“官渡之战”的对阵双方是谁？", "曹操和袁绍", "刘备和孙权", "曹操和刘备", "孙权和刘璋", "200年官渡之战，曹操以少胜多大破袁绍，统一了北方。这是中国历史上著名的以少胜多战役。");
add("文史", 3, "“淝水之战”中以少胜多的是哪一方？", "东晋", "前秦", "北魏", "东吴", "383年淝水之战，东晋8万军队打败前秦80多万大军。前秦瓦解，北方重新陷入分裂。");
add("文史", 3, "“陈桥兵变”中被拥立为皇帝的是谁？", "赵匡胤", "赵光义", "柴荣", "李世民", "960年赵匡胤在陈桥驿被部下黄袍加身，拥立为帝，建立北宋。“黄袍加身”说的就是这件事。");
add("文史", 3, "“杯酒释兵权”的是哪位皇帝？", "宋太祖", "宋太宗", "明太祖", "唐太宗", "宋太祖赵匡胤设宴请功臣喝酒，劝他们交出兵权换享荣华富贵，解除了武将专权的威胁。");
add("文史", 3, "“澶渊之盟”的签约双方是谁？", "北宋与辽", "北宋与西夏", "南宋与金", "唐朝与吐蕃", "1005年北宋与辽在澶渊（今河南濮阳）议和，宋每年给辽岁币，换来一百多年和平。");
add("文史", 3, "“王安石变法”发生在哪个朝代？", "北宋", "唐朝", "明朝", "清朝", "北宋神宗时，王安石推行青苗法、募役法等新政，想富国强兵。变法触动了旧贵族利益，最终失败。");
add("文史", 3, "“指鹿为马”的是谁？", "赵高", "李斯", "秦桧", "魏忠贤", "秦朝宦官赵高指着鹿说它是马，群臣或附和或沉默，他借此看出哪些大臣顺从自己。“指鹿为马”比喻颠倒黑白。");
add("文史", 3, "“甲午战争”中壮烈牺牲的爱国将领是谁？", "邓世昌", "林则徐", "左宗棠", "丁汝昌", "1894年黄海海战中，邓世昌指挥致远舰撞向日舰，不幸牺牲。他是甲午战争中最著名的民族英雄。");
add("文史", 3, "“西安事变”中被扣留的是谁？", "蒋介石", "张学良", "杨虎城", "毛泽东", "1936年张学良、杨虎城在西安扣留蒋介石，逼他联共抗日。事变和平解决，抗日民族统一战线初步形成。");
add("文史", 3, "“马可·波罗”来中国时，中国正处于哪个朝代？", "元朝", "唐朝", "宋朝", "明朝", "意大利人马可·波罗在元朝时来到中国，住了十几年。回国后口述《马可·波罗游记》，让欧洲人知道了富庶的东方。");
add("文史", 3, "“都江堰”是哪位水利家主持修建的？", "李冰", "郑国", "郭守敬", "郦道元", "战国时秦国太守李冰父子主持修建都江堰，巧妙地分水治水。两千多年来它一直灌溉着成都平原，至今仍在使用。");
add("文史", 4, "“田忌赛马”中，给田忌出主意的是谁？", "孙膑", "庞涓", "吴起", "乐毅", "孙膑让田忌用下等马对上等马、上等马对中等马、中等马对下等马，三局两胜赢了齐威王。这是“扬长避短”的经典例子。");
add("文史", 4, "“围魏救赵”是谁提出的计策？", "孙膑", "吴起", "庞涓", "白起", "魏国攻打赵国，孙膑建议直捣魏国都城，魏军回救，齐军在桂陵设伏大胜。“围魏救赵”比喻攻敌后方解友军之围。");
add("文史", 4, "“退避三舍”的主人公是谁？", "晋文公", "楚庄王", "齐桓公", "秦穆公", "晋文公为报楚国收留之恩，与楚军交战时主动后退九十里（一舍三十里）。后来晋国果然大胜，晋文公成为春秋五霸之一。");
add("文史", 4, "“一鼓作气”出自哪场战役？", "长勺之战", "官渡之战", "赤壁之战", "淝水之战", "“一鼓作气，再而衰，三而竭”是曹刿在长勺之战中说的。鲁军趁齐军三次击鼓后士气低落时反击，大获全胜。");
add("文史", 4, "“王侯将相宁有种乎”是哪次起义中喊出的口号？", "大泽乡起义", "黄巾起义", "瓦岗起义", "黄巢起义", "公元前209年，陈胜、吴广在大泽乡起义，喊出“王侯将相宁有种乎”，这是中国历史上第一次农民大起义。");
add("文史", 4, "“鸿门宴”上，项羽最倚重的谋士是谁？", "范增", "张良", "陈平", "英布", "鸿门宴上范增多次示意项羽杀掉刘邦，项羽犹豫不决，刘邦趁机逃走。项羽后来猜忌范增，范增愤而离去，不久病死。");
add("文史", 4, "“萧何月下追韩信”中，被追回的是谁？", "韩信", "张良", "萧何", "曹参", "韩信投奔刘邦却只当了小官，一气之下出走。萧何连夜追回，向刘邦力荐，韩信被拜为大将，后来立下赫赫战功。");
add("文史", 4, "“明修栈道，暗度陈仓”是谁的计策？", "韩信", "张良", "萧何", "刘邦", "韩信派人明着修复栈道迷惑项羽，暗地带兵走陈仓小道突袭关中。这是“声东击西”的经典战例。");
add("文史", 4, "“春秋五霸”一般不包括下面哪一位？", "汉武帝", "齐桓公", "晋文公", "楚庄王", "“春秋五霸”指春秋时期先后称霸的诸侯，如齐桓公、晋文公、楚庄王等。汉武帝是西汉皇帝，比春秋晚了几百年。");
add("文史", 4, "“光荣革命”发生在哪个国家？", "英国", "法国", "美国", "俄国", "1688年英国议会赶走詹姆斯二世，迎来威廉三世，几乎没流血。之后议会通过《权利法案》，确立了君主立宪制。");
add("文史", 4, "“百年战争”交战的双方是谁？", "英格兰和法国", "英格兰和西班牙", "法国和西班牙", "奥地利和普鲁士", "1337年到1453年，英格兰和法国为争夺王位打了一百多年。法国女英雄圣女贞德就涌现在这场战争中。");
add("文史", 4, "《大宪章》是在哪个国家签署的？", "英国", "法国", "美国", "德国", "1215年英国贵族逼迫约翰王签署《大宪章》，限制王权。它是英国宪政的起点，影响了后来的《权利法案》和美国宪法。");
add("文史", 4, "“文艺复兴三杰”不包括下面哪一位？", "莎士比亚", "达·芬奇", "米开朗基罗", "拉斐尔", "“文艺复兴三杰”是达·芬奇、米开朗基罗和拉斐尔，都是画家。莎士比亚是英国大戏剧家，比他们晚了约一百年。");
add("文史", 4, "“十月革命”发生在哪个国家？", "俄国", "法国", "中国", "德国", "1917年列宁领导十月革命，建立了世界上第一个社会主义国家苏俄。它鼓舞了包括中国在内的各国革命者。");
add("文史", 4, "“诺曼底登陆”发生在哪一年？", "1944年", "1941年", "1945年", "1939年", "1944年6月6日，盟军在法国诺曼底登陆，开辟欧洲第二战场。这是人类历史上规模最大的登陆作战，加速了二战胜利。");

// ───────────── 新增 · 理科 ─────────────
add("理科", 1, "中国最大的岛屿是？", "台湾岛", "海南岛", "崇明岛", "舟山岛", "台湾岛面积约3.6万平方公里，是中国第一大岛。海南岛是第二大岛，崇明岛是世界最大的河口冲积岛。");
add("理科", 1, "世界上最大的岛屿是？", "格陵兰岛", "冰岛", "马达加斯加岛", "苏门答腊岛", "格陵兰岛面积约216万平方公里，是世界第一大岛，80%以上被冰雪覆盖，属于丹麦。很多人以为它是独立国家，其实不是。");
add("理科", 1, "黄河最后注入哪个海？", "渤海", "黄海", "东海", "南海", "黄河全长5464公里，自西向东流经9个省区，最后在山东东营注入渤海。渤海是中国的内海，黄河每年带去大量泥沙，让入海口不断向外长。");
add("理科", 1, "长江最后注入哪个海？", "东海", "黄海", "渤海", "南海", "长江全长6300多公里，是中国第一长河，最后在上海崇明岛附近注入东海。长江入海口水量巨大，上海的淡水主要就靠它。");
add("理科", 1, "被称为“枫叶之国”的是哪个国家？", "加拿大", "美国", "俄罗斯", "芬兰", "加拿大的国旗正中就是一片红色枫叶。加拿大国土横跨北美洲北部，枫树在那里非常常见，秋天满山红叶。");
add("理科", 1, "被称为“风车之国”的是哪个国家？", "荷兰", "丹麦", "比利时", "瑞士", "荷兰地势低洼，历史上用风车抽水排涝、磨面粉，全盛时有一万多座风车。现在风车成了荷兰的标志，郁金香和木鞋也是那里的特产。");
add("理科", 1, "被称为“袋鼠之国”的是哪个国家？", "澳大利亚", "新西兰", "南非", "巴西", "袋鼠是澳大利亚独有的动物，国徽上就有一只袋鼠和一只鸸鹋。有意思的是，这两种动物都只会往前走，象征国家永远向前。");
add("理科", 1, "中国面积最大的省级行政区是？", "新疆维吾尔自治区", "西藏自治区", "内蒙古自治区", "青海省", "新疆面积约166万平方公里，占全国六分之一，相当于3个法国那么大。从新疆最东边开车到最西边，要开将近两天。");
add("理科", 1, "青藏高原被称为什么？", "世界屋脊", "世界屋顶", "地球之巅", "雪域高原", "青藏高原平均海拔4000米以上，被称为“世界屋脊”。长江、黄河、澜沧江都发源于这里，所以它还被称为“亚洲水塔”。");
add("理科", 1, "日本最高的山峰是？", "富士山", "阿苏山", "白山", "立山", "富士山海拔3776米，是日本第一高峰，也是日本的象征。它其实是一座活火山，上一次喷发在1707年，山顶常年积雪，非常漂亮。");
add("理科", 1, "非洲最长的河流是？", "尼罗河", "刚果河", "赞比西河", "尼日尔河", "尼罗河全长约6670公里，是非洲最长的河流，流经埃及等11个国家。古埃及文明就诞生在尼罗河两岸，离开了它就没有金字塔。");
add("理科", 1, "西湖位于哪座城市？", "杭州", "苏州", "扬州", "无锡", "西湖在浙江杭州，有断桥、苏堤、白堤等著名景点。古人说“上有天堂，下有苏杭”，苏杭里的“杭”就是杭州。");
add("理科", 1, "中国最大的淡水湖是？", "鄱阳湖", "洞庭湖", "太湖", "洪泽湖", "鄱阳湖在江西，面积随季节变化，最大时超过4000平方公里。它还是白鹤等候鸟过冬的天堂，每年冬天有几十万只候鸟飞来。");
add("理科", 1, "下面哪座山不是“五岳”之一？", "黄山", "泰山", "华山", "衡山", "五岳是东岳泰山、西岳华山、南岳衡山、北岳恒山、中岳嵩山。黄山虽然也很有名，以奇松怪石著称，但不在五岳之列。");
add("理科", 2, "中国最长的内流河是？", "塔里木河", "黑河", "石羊河", "疏勒河", "塔里木河全长2179公里，是中国最长的内流河。“内流河”指不流入大海、最后消失在沙漠或湖泊里的河，塔里木河就消失在塔克拉玛干沙漠里。");
add("理科", 2, "土耳其的首都是？", "安卡拉", "伊斯坦布尔", "伊兹密尔", "安塔利亚", "很多人以为是伊斯坦布尔，其实土耳其的首都是安卡拉。伊斯坦布尔是土耳其最大城市和经济中心，但1923年建国时定都选了位置更居中的安卡拉。");
add("理科", 2, "巴西的首都是？", "巴西利亚", "里约热内卢", "圣保罗", "萨尔瓦多", "巴西的首都是巴西利亚，不是里约也不是圣保罗。它是1960年从零开始规划建设的新首都，从空中看整个城市像一架飞机。");
add("理科", 2, "世界上流量最大的河流是？", "亚马逊河", "刚果河", "尼罗河", "长江", "亚马逊河的流量大得惊人，约占全世界河流总入海量的五分之一，相当于7条长江。它流域内的热带雨林是“地球之肺”。");
add("理科", 2, "世界上最长的山脉是？", "安第斯山脉", "落基山脉", "喜马拉雅山脉", "阿尔卑斯山脉", "安第斯山脉纵贯南美洲西岸，全长约8900公里，是世界最长的山脉。喜马拉雅山脉虽然更高，但长度只有约2400公里。");
add("理科", 2, "世界上最大的珊瑚礁群是？", "大堡礁", "红海珊瑚礁", "马尔代夫环礁", "帕劳珊瑚礁", "大堡礁在澳大利亚东北海岸，长约2300公里，是世界最大的珊瑚礁系统，从太空都能看到。它由上千个珊瑚礁组成，生活着1500多种鱼。");
add("理科", 2, "非洲最高的山峰是？", "乞力马扎罗山", "肯尼亚山", "鲁文佐里山", "阿特拉斯山", "乞力马扎罗山海拔5895米，是非洲最高峰。神奇的是它位于赤道附近，山顶却终年积雪，被称为“赤道上的雪山”。");
add("理科", 2, "被称为“千湖之国”的是哪个国家？", "芬兰", "瑞典", "挪威", "加拿大", "芬兰境内有大大小小近19万个湖泊，所以叫“千湖之国”。这些湖大多是冰川运动留下来的，夏天湖边木屋加桑拿是芬兰人的标配生活。");
add("理科", 2, "被称为“钟表王国”的是哪个国家？", "瑞士", "德国", "奥地利", "法国", "瑞士手表闻名世界，劳力士、欧米茄都产自那里。瑞士多山，冬天农民没农活干，就在家里做钟表，慢慢做成了世界第一。");
add("理科", 2, "世界上最大的群岛国家是？", "印度尼西亚", "菲律宾", "日本", "英国", "印度尼西亚由1.7万多个岛屿组成，是世界最大的群岛国家。它的国土横跨赤道，东西宽5000多公里，坐飞机横穿全国要飞6个小时。");
add("理科", 2, "中国最大的咸水湖是？", "青海湖", "纳木错", "色林错", "乌伦古湖", "青海湖面积约4500平方公里，是中国最大的湖泊，也是最大的咸水湖。它还是鸟岛的所在地，每年有十万只候鸟来这里繁殖。");
add("理科", 2, "中国最大的沙漠是？", "塔克拉玛干沙漠", "古尔班通古特沙漠", "巴丹吉林沙漠", "腾格里沙漠", "塔克拉玛干沙漠在新疆，面积约33万平方公里，是中国最大、世界第二大的流动沙漠。“塔克拉玛干”在维吾尔语里是“走得进、走不出”的意思。");
add("理科", 2, "“桂林山水甲天下”的桂林，在哪个省级行政区？", "广西壮族自治区", "广东省", "湖南省", "贵州省", "桂林在广西壮族自治区。那里的喀斯特地貌形成了千奇百怪的峰林，漓江水清得能看见江底，难怪古人说桂林山水甲天下。");
add("理科", 2, "港珠澳大桥连接香港、珠海和哪座城市？", "澳门", "深圳", "广州", "中山", "港珠澳大桥全长55公里，是世界最长的跨海大桥，连接香港、珠海和澳门。开车过桥，海底隧道那段是从海底穿过去的。");
add("理科", 3, "瑞士的首都是？", "伯尔尼", "苏黎世", "日内瓦", "巴塞尔", "瑞士的首都是伯尔尼，不是苏黎世也不是日内瓦。伯尔尼老城区是世界文化遗产，城里还养着几只棕熊——熊正是伯尔尼的象征。");
add("理科", 3, "加拿大的首都是？", "渥太华", "多伦多", "温哥华", "蒙特利尔", "加拿大首都是渥太华，不是多伦多。1857年英国女王在几个候选城市里圈定了渥太华，理由是它位置居中，又远离美国边境，比较安全。");
add("理科", 3, "世界上最深的湖泊是？", "贝加尔湖", "坦噶尼喀湖", "里海", "维多利亚湖", "贝加尔湖在俄罗斯西伯利亚，最深处1637米，是世界最深的湖。它还储存了全球约五分之一的地表淡水，湖水清澈得能看见40米深。");
add("理科", 3, "世界上面积最大的高原是？", "巴西高原", "青藏高原", "德干高原", "墨西哥高原", "巴西高原面积约500万平方公里，是世界最大的高原。青藏高原虽然最高，但面积只有约250万平方公里，排第二。");
add("理科", 3, "世界上最长的两国国境线，在哪两个国家之间？", "美国和加拿大", "俄罗斯和中国", "蒙古和中国", "哈萨克斯坦和俄罗斯", "美国和加拿大的国境线长达8891公里，是世界最长的两国边界。这条边界基本不设防，被称为“世界上最长的和平边界”。");
add("理科", 3, "世界上最大的内陆国是？", "哈萨克斯坦", "蒙古", "乍得", "尼日尔", "哈萨克斯坦面积272万平方公里，是世界最大的内陆国（不靠海的国家）。它地跨欧亚两洲，石油和矿产资源非常丰富。");
add("理科", 3, "黄河发源于哪座山脉？", "巴颜喀拉山", "昆仑山", "唐古拉山", "祁连山", "黄河发源于青海巴颜喀拉山北麓。“巴颜喀拉”在蒙古语里是“富饶青色的山”，黄河、长江的源头都在这一带，难怪叫“中华水塔”。");
add("理科", 3, "长江发源于哪座山脉？", "唐古拉山", "巴颜喀拉山", "横断山脉", "念青唐古拉山", "长江正源沱沱河，发源于唐古拉山脉主峰格拉丹东的冰川。从源头到入海口，长江落差超过5000米，难怪水流那么有劲。");
add("理科", 3, "澜沧江流出中国之后叫什么？", "湄公河", "萨尔温江", "伊洛瓦底江", "红河", "澜沧江发源于青海，流出中国后叫湄公河，流经缅甸、老挝、泰国、柬埔寨、越南5国，最后注入南海。一条河穿6个国家，在世界上也不多见。");
add("理科", 3, "世界第二高峰是？", "乔戈里峰", "干城章嘉峰", "马卡鲁峰", "洛子峰", "乔戈里峰海拔8611米，是世界第二高峰，位于中国和巴基斯坦边境。它比珠峰难爬得多，登顶死亡率超过20%，被称为“野蛮巨峰”。");
add("理科", 3, "世界上最长的裂谷是？", "东非大裂谷", "贝加尔裂谷", "莱茵裂谷", "死海裂谷", "东非大裂谷纵贯非洲东部，全长约6000公里，是世界最长的裂谷带。地质学家说，再过几千万年，非洲东部可能会从大陆上撕裂出去。");
add("理科", 3, "中国领土东西横跨几个时区？", "5个", "3个", "4个", "6个", "中国从东五区一直横跨到东九区，共5个时区。但全国统一用北京时间（东八区），所以新疆的孩子冬天早上10点天才亮，上学却和我们一样准时。");
add("理科", 3, "赤道穿过的南美洲国家中，不包括哪一个？", "阿根廷", "巴西", "厄瓜多尔", "哥伦比亚", "赤道穿过厄瓜多尔、哥伦比亚和巴西三个南美国家——厄瓜多尔国名本身就是西班牙语的“赤道”。阿根廷在南回归线以南，离赤道远着呢。");
add("理科", 3, "世界上唯一一座横跨两大洲的城市是？", "伊斯坦布尔", "莫斯科", "安卡拉", "圣彼得堡", "伊斯坦布尔被博斯普鲁斯海峡分成两半，一半在欧洲、一半在亚洲，是世界上唯一横跨两大洲的城市。当地人调侃：堵车时从亚洲开车到欧洲上班是日常。");
add("理科", 4, "世界上海拔最高的咸水湖是？", "纳木错", "青海湖", "的的喀喀湖", "死海", "纳木错在西藏，海拔4718米，是世界上海拔最高的咸水湖。“纳木错”在藏语里是“天湖”，湖水蓝得像天空掉在地上，藏民心中的圣湖。");
add("理科", 4, "欧洲最高的山峰是？", "厄尔布鲁士峰", "勃朗峰", "马特洪峰", "大格洛克纳山", "厄尔布鲁士峰海拔5642米，在俄罗斯境内的大高加索山脉，是欧洲最高峰。勃朗峰（4810米）只是阿尔卑斯山的最高峰，排第二。");
add("理科", 4, "世界上位置最靠北的首都，是哪个城市？", "雷克雅未克", "赫尔辛基", "奥斯陆", "斯德哥尔摩", "冰岛首都雷克雅未克位于北纬64度，是世界最北的首都。那里冬天每天只有4小时白天，但能看到极光，地热还便宜到可以露天泡温泉。");
add("理科", 4, "世界上位置最靠南的首都，是哪个城市？", "惠灵顿", "堪培拉", "布宜诺斯艾利斯", "开普敦", "新西兰首都惠灵顿位于南纬41度，是世界最南的首都。它风特别大，有“风城”的外号，站在海边一不小心帽子就飞了。");
add("理科", 4, "世界上横跨时区最多的国家是？", "法国", "俄罗斯", "美国", "中国", "法国本土只有1个时区，但加上遍布全球的海外领地，一共横跨12个时区，世界第一。俄罗斯虽然本土最宽，也只有11个时区。");
add("理科", 4, "世界上每天最早进入新一天的国家是？", "基里巴斯", "汤加", "萨摩亚", "新西兰", "太平洋岛国基里巴斯的莱恩群岛使用东十四区时间，比北京时间早6小时，是全世界最早跨入新一天的地方。那里的人总能先过上元旦。");
add("理科", 4, "下面哪个国家没有一条常年流淌的河流？", "沙特阿拉伯", "巴西", "印度", "中国", "沙特阿拉伯是世界上最大的、没有常年性河流的国家，淡水全靠海水淡化和地下水。巴西有亚马逊河，印度有恒河，中国更不用说，江河多得很。");
add("理科", 4, "世界上人口密度最高的国家是？", "摩纳哥", "新加坡", "巴林", "马耳他", "摩纳哥只有2平方公里，却住了近4万人，人口密度世界第一。这个袖珍小国以赌场和F1街道赛闻名，还是很多富豪的免税天堂。");
add("理科", 4, "世界上年降水量最多的地方是？", "乞拉朋齐", "火烧寮", "怀厄莱阿莱", "阿塔卡马", "印度东北部的乞拉朋齐年均降水量超过11000毫米，是公认的“世界雨极”。它正对着孟加拉湾，湿热气流被喜马拉雅山一挡，雨就下个不停。");
add("理科", 4, "世界上最干燥的地区是？", "阿塔卡马沙漠", "撒哈拉沙漠", "卢特沙漠", "辛普森沙漠", "智利的阿塔卡马沙漠是世界最干燥的地方，有些气象站几十年没测到过降水。那里干到连细菌都很难存活，美国宇航局拿它模拟火星环境。");
add("理科", 4, "世界上最冷的人类定居点之一，是俄罗斯的哪里？", "奥伊米亚康", "雷克雅未克", "乌兰巴托", "哈尔滨", "奥伊米亚康在西伯利亚，冬季气温常跌破零下50度，历史极端低温接近零下68度。当地人出门睫毛会结冰，汽车熄火后就再也打不着了。");
add("理科", 4, "中国年降水量最多的地方是？", "火烧寮", "吐鲁番", "漠河", "曾母暗沙", "台湾新北市平溪区的火烧寮，年均降水量约6500毫米，是中国年降水量最多的地方。而吐鲁番一年才下十几毫米，真是两个极端。");
add("理科", 4, "世界上最大的火山口湖是？", "多巴湖", "长白山天池", "火山口湖", "陶波湖", "印度尼西亚苏门答腊岛的多巴湖，是约7万年前超级火山喷发后形成的，长100公里，是世界最大的火山口湖。那次喷发据说差点让人类灭绝。");
add("理科", 1, "圆周率π大约等于多少？", "3.14", "1.41", "2.71", "6.28", "π是圆周长和直径的比值，是个无限不循环小数。祖冲之在1500多年前就把它算到了3.1415926和3.1415927之间，领先世界近千年。");
add("理科", 1, "闰年一年有多少天？", "366天", "365天", "364天", "367天", "地球绕太阳一圈约365天6小时，多出来的6小时攒四年就是一整天，所以每四年有个闰年，二月会多出2月29日。");
add("理科", 1, "七巧板是由几块板拼成的？", "7块", "5块", "6块", "8块", "七巧板有5块三角形、1块正方形、1块平行四边形，一共7块。它起源于中国，能拼出人物、动物等上千种图案。");
add("理科", 1, "在除法里，哪个数不能做除数？", "0", "1", "任何数都可以", "小数", "0做除数没有意义：比如5÷0，找不到一个数乘以0等于5。所以数学里规定，除数不能是0。");
add("理科", 1, "平面上，三角形三个内角加起来是多少度？", "180度", "90度", "270度", "360度", "任何平面三角形的内角和都是180度，这是古希腊数学家欧几里得证明的几何基本定理之一。");
add("理科", 1, "把一张纸连续对折3次，会变成几层？", "8层", "6层", "9层", "12层", "对折一次2层、两次4层、三次8层，层数每次翻倍。纸越折越厚，所以一张普通纸很难对折超过7次。");
add("理科", 1, "下面哪个数是质数？", "7", "4", "6", "9", "质数是只能被1和它本身整除的数。4=2×2、6=2×3、9=3×3都不是质数，只有7是。");
add("理科", 1, "最小的质数是几？", "2", "1", "3", "0", "1不是质数，因为它只有一个因数。2是最小的质数，也是唯一的偶质数，其余质数全是奇数。");
add("理科", 2, "勾股定理说的是哪种三角形的边长关系？", "直角三角形", "锐角三角形", "钝角三角形", "等边三角形", "勾股定理说直角三角形两条直角边的平方和等于斜边的平方，比如3、4、5。中国的商高和古希腊的毕达哥拉斯分别独立发现了它。");
add("理科", 2, "零下5摄氏度通常记作什么？", "-5℃", "5℃", "0℃", "+5℃", "零下的温度用负数表示，零下5度记作-5℃。负数在中国古代《九章算术》里就开始使用了，比西方早一千多年。");
add("理科", 2, "哪个数的平方等于16？", "4", "2", "8", "16", "4×4=16，所以4的平方是16。（严格说-4的平方也是16，不过选项里没有它。）");
add("理科", 2, "用圆规画圆时，圆规两脚之间的距离决定了圆的什么？", "半径", "圆心", "直径", "周长", "圆规一脚定圆心，两脚之间的距离就是半径。半径决定圆的大小，圆心决定圆的位置，两者缺一不可。");
add("理科", 2, "掷一枚均匀的硬币，出现正面的概率是多少？", "二分之一", "三分之一", "四分之一", "百分之百", "硬币只有正反两面，均匀的话各占一半，概率就是二分之一。有趣的是：连出10次正面后，第11次正面的概率仍然是二分之一。");
add("理科", 2, "下面哪个大写英文字母不是轴对称图形？", "F", "A", "H", "O", "A、H、O都能找到对称轴（H和O甚至有两条），F无论怎么折两边都对不上，所以不是轴对称图形。");
add("理科", 2, "像圆周率这样无限不循环的小数，叫做什么数？", "无理数", "有理数", "整数", "自然数", "无限不循环小数叫做无理数，π和根号2都是。古希腊人发现根号2是无理数时，据说在数学界引起了一场大风波。");
add("理科", 2, "把一条纸带扭转半圈再把两端粘起来，得到的是什么？", "莫比乌斯环", "圆柱面", "球面", "圆锥面", "这就是莫比乌斯环，它只有一个面：一只蚂蚁沿着它爬，能走遍整个面而不翻过边缘。很多传送带用这个原理让两面磨损均匀。");
add("理科", 3, "数学里，-1的平方根通常记作什么？", "i", "e", "π", "∞", "-1的平方根记作i，叫虚数单位，i²=-1。有了它，数学家建立了复数系，现代电子学和量子力学都离不开复数。");
add("理科", 3, "以10为底，100的对数是多少？", "2", "10", "1", "100", "对数问的是“10的几次方等于100”，10²=100，所以lg100=2。对数是纳皮尔发明的，曾让天文学家的计算量大大减少。");
add("理科", 3, "把1到3的整数写成集合，下面哪个写法正确？", "{1,2,3}", "(1,2,3)", "[1,2,3]", "<1,2,3>", "集合用大括号表示，{1,2,3}正确。圆括号多用来表示区间或坐标，方括号和尖括号在数学里另有含义。");
add("理科", 3, "一次函数y=2x+1的图像是什么形状？", "直线", "抛物线", "圆", "双曲线", "一次函数的图像永远是直线。这里2是斜率（x每增加1，y就增加2），1是图像和y轴交点的位置。");
add("理科", 3, "sin30°等于多少？", "二分之一", "三分之一", "二分之根号二", "1", "sin30°=1/2是最常用的特殊角三角函数值之一。在直角三角形里，30°角所对的直角边正好是斜边的一半。");
add("理科", 3, "黄金分割比大约是多少？", "0.618", "0.5", "0.707", "0.866", "黄金分割比约0.618，据说按这个比例画的长方形最耐看。古希腊建筑和文艺复兴名画里，常常能找到它的身影。");
add("理科", 3, "我们现在用的阿拉伯数字，最早起源于哪里？", "古印度", "古埃及", "古巴比伦", "古希腊", "阿拉伯数字其实是古印度人发明的，经阿拉伯人之手传到欧洲，才得了这个名字。连“0”这个符号也是印度人的伟大发明。");
add("理科", 4, "微积分的创立，除了牛顿，通常还归功于谁？", "莱布尼茨", "欧拉", "高斯", "笛卡尔", "牛顿和莱布尼茨各自独立创立了微积分，还为此打过优先权官司。现在通用的∫符号和dy/dx记号，就是莱布尼茨发明的。");
add("理科", 4, "拓扑学里说，咖啡杯和哪种东西是“等价”的？", "甜甜圈", "实心球", "立方体", "碗", "拓扑学不关心形状，只关心“洞”的数量。咖啡杯的把手有个洞，甜甜圈中间也有个洞，所以它俩等价；没有洞的实心球就不等价。");
add("理科", 4, "整数和偶数，哪个“更多”？", "一样多", "整数更多", "偶数更多", "无法比较", "一样多！每个整数n都能和偶数2n一一配对，谁也不多谁也不少。数学家用“一一对应”来比较无穷的大小，这是康托尔的著名结论。");
add("理科", 4, "困扰数学家300多年的费马大定理，最终是被谁证明的？", "怀尔斯", "高斯", "欧拉", "希尔伯特", "1994年，英国数学家怀尔斯经过7年闭关研究证明了它。费马当年在书页边写道：我想到了绝妙的证明，可惜空白太小写不下。");
add("理科", 4, "在球面上画一个三角形，它的内角和会怎么样？", "大于180度", "等于180度", "小于180度", "不确定", "球面是弯曲的，上面的“直线”都是大圆弧，三角形内角和大于180度。比如从北极到赤道取两点，能画出三个直角的三角形。");
add("理科", 4, "著名的“哥尼斯堡七桥问题”是被哪位数学家解决的？", "欧拉", "牛顿", "拉格朗日", "傅里叶", "1736年欧拉证明一次走遍七座桥而不重复是不可能的，顺手开创了图论。图论现在是计算机网络和导航的数学基础。");
add("理科", 4, "0.999…（9无限循环）到底等不等于1？", "等于1", "比1小一点", "比1大一点", "数学家也没定论", "等于1。因为1/3=0.333…，两边同时乘以3，就得到1=0.999…。无限循环小数和它的极限值其实是同一个数。");
add("理科", 1, "冰能浮在水面上，说明冰的密度和水比怎么样？", "比水小", "比水大", "和水一样", "和温度有关不一定", "冰浮起来说明它比水轻，也就是密度比水小。水在4℃时密度最大，结冰反而膨胀，这是水最反常也最重要的性质之一。");
add("理科", 1, "太阳每天东升西落，主要是因为地球在做什么？", "绕着地轴自转", "绕太阳公转", "在银河系里漂移", "跟着月亮跑", "地球自西向东自转一圈约24小时，我们跟着转，就感觉太阳东升西落了。而绕太阳公转带来的是四季变化，不是一天。");
add("理科", 1, "冬天，窗户上的“冰花”通常结在哪一面？", "室内一面", "室外一面", "两面都有", "随机的", "冰花是室内暖湿空气遇到冰冷的玻璃，水蒸气直接凝成冰晶，所以长在室内一面。室外干冷的空气可造不出它。");
add("理科", 1, "看彩虹时，太阳应该在你的哪一边？", "背后", "正前方", "头顶正上方", "脚下", "彩虹出现在和太阳相反的方向，所以看彩虹时太阳一定在你背后。早晚太阳位置低时，最容易看到完整的彩虹。");
add("理科", 1, "磁铁能吸住下面哪种金属？", "铁", "铜", "铝", "金", "磁铁只能吸住铁、钴、镍等少数磁性金属，吸不住铜、铝、金。所以废品站用大磁铁一吸，就能把铁分拣出来。");
add("理科", 1, "雷雨天，为什么总是先看到闪电、后听到雷声？", "光比声音跑得快得多", "闪电离我们更近", "雷声要绕路", "人眼比耳朵灵敏", "光每秒跑30万公里，声音每秒只跑约340米。闪电和雷声同时产生，光瞬间就到，声音却要慢慢赶路。");
add("理科", 1, "热气球里充的是什么让它升空的？", "热空气", "氢气", "氦气", "真空", "热气球靠燃烧器把空气加热，热空气比冷空气轻，浮力就把气球托起来了。氢气虽轻但易爆，现在民用热气球都用热空气。");
add("理科", 2, "“给我一个支点，我就能撬动地球”这句豪言是谁说的？", "阿基米德", "牛顿", "伽利略", "亚里士多德", "古希腊的阿基米德发现了杠杆原理：动力×动力臂=阻力×阻力臂。他还发现了浮力定律，是古代最伟大的科学家之一。");
add("理科", 2, "传说伽利略在比萨斜塔上同时扔下一轻一重两个球，结果怎样？", "同时落地", "重的先落地", "轻的先落地", "轻的飘走了", "传说两个球同时落地，说明物体下落快慢和重量无关（不计空气阻力时）。这个实验动摇了亚里士多德统治千年的错误观点。");
add("理科", 2, "电压的单位是什么？", "伏特", "安培", "欧姆", "瓦特", "电压单位是伏特（V），为纪念发明电池的意大利科学家伏打。安培是电流单位，欧姆是电阻单位，瓦特是功率单位，别搞混了。");
add("理科", 2, "牛顿让一束白光穿过三棱镜，这个实验证明了什么？", "白光由多种色光组成", "光沿直线传播", "光速是有限的", "三棱镜能放大", "白光穿过三棱镜分出了红橙黄绿蓝靛紫七色光，证明白光是复色光。这个实验开创了光谱学，科学家靠它分析星星的成分。");
add("理科", 2, "凸透镜对光线起什么作用？", "会聚", "发散", "反射", "什么都不做", "凸透镜中间厚、边缘薄，能把平行光会聚到一点。放大镜、老花镜和照相机镜头里都有它。");
add("理科", 2, "近视眼看不清远处，应该配哪种透镜的眼镜？", "凹透镜", "凸透镜", "平面镜", "三棱镜", "近视是晶状体太“给力”，把像成在了视网膜前面。凹透镜能把光发散一下，让像正好落在视网膜上。");
add("理科", 2, "指南针静止时，红色的一端通常指向哪个方向？", "北方", "东方", "南方", "西方", "指南针的红色端是N极，静止时会指向北方。中国古代的司南是世界上最早的指南仪器，比欧洲早了一千多年。");
add("理科", 2, "马德堡半球实验是为了证明什么？", "大气压的存在", "地球是圆的", "真空里没有声音", "铜比铁结实", "1654年，两个铜半球抽成真空后，十几匹马都拉不开，证明大气压强巨大。我们平时感觉不到，是因为身体内外气压平衡。");
add("理科", 3, "X射线是谁发现的？", "伦琴", "居里夫人", "爱迪生", "法拉第", "1895年德国物理学家伦琴发现X射线，第一届诺贝尔物理学奖就颁给了他。现在X射线的剂量单位就叫“伦琴”。");
add("理科", 3, "爱因斯坦质能方程E=mc²里，c代表什么？", "光速", "电荷量", "常数3", "比热容", "c是真空中的光速，约每秒30万公里。这个公式说质量就是“冻住”的能量，核电站发电和太阳发光都靠它。");
add("理科", 3, "超导现象指的是什么？", "导体电阻变为零", "电流速度超过光速", "超高电压输电", "磁铁失去磁性", "某些材料冷却到极低温度时，电阻会突然变为零，电流可以永远流下去不耗电。1911年昂内斯在液氦中首先发现了它。");
add("理科", 3, "救护车呼啸而过时，笛声由尖变钝，这是哪种效应？", "多普勒效应", "光电效应", "康普顿效应", "蝴蝶效应", "这就是多普勒效应：声源靠近时声波被“压缩”，音调变高；远离时被“拉长”，音调变低。交警测速仪和天文观测星系退行都用它。");
add("理科", 3, "爱因斯坦是因为哪个发现获得诺贝尔奖的？", "光电效应", "相对论", "布朗运动", "质能方程", "出人意料吧？爱因斯坦1921年获奖靠的是解释光电效应（证明了光的粒子性），而不是相对论。当时评委觉得相对论还不够“实锤”。");
add("理科", 3, "发电机是根据什么原理把机械能变成电能的？", "电磁感应", "电流的热效应", "光电效应", "压电效应", "法拉第发现：闭合线圈里的磁场变化时就会产生电流。现代所有发电站——火电、水电、风电、核电，本质上都是“摇”磁铁发电。");
add("理科", 3, "宇航员在空间站里“飘”起来，是因为那里没有重力吗？", "不是，是处于失重状态", "是的，太空没有重力", "是因为穿了宇航服", "是因为舱内有鼓风机", "不是没有重力！空间站每秒绕地球飞8公里，和宇航员一起做“自由落体”，人就感觉不到重量了，这叫失重。空间站轨道上的重力还有地面的约九成。");
add("理科", 3, "现在的核电站利用的是核裂变还是核聚变？", "核裂变", "核聚变", "两种都有", "都不是，烧煤", "都是核裂变：铀-235原子核被中子撞裂，释放巨大能量烧水发电。太阳发光用的是核聚变，人类可控核聚变还没实现。");
add("理科", 4, "绝对零度是摄氏多少度？", "-273.15℃", "0℃", "-100℃", "273.15℃", "绝对零度是-273.15℃，是温度的理论下限，到那时原子热运动完全停止。现实中只能无限接近，永远达不到。");
add("理科", 4, "晴朗的天空为什么是蓝色的？", "阳光中蓝光被空气散射", "大海反射的", "臭氧是蓝色的", "人眼的错觉", "阳光中的蓝紫光波长短，最容易被空气分子“撞”得四散（瑞利散射），于是整个天空都泛着蓝。日出日落时蓝光散没了，就只剩红霞。");
add("理科", 4, "海洋潮汐的涨落主要是由什么引起的？", "月球引力", "太阳引力", "海底地震", "地球自转离心力", "主要是月球引力：月球把正对它那面的海水“拽”起来。太阳引力也有份，但只有月球的大约一半。钱塘江大潮就和月相有关。");
add("理科", 4, "深海的海水看起来是蓝色，主要原因是什么？", "水分子吸收了红光", "天空倒映", "海里有蓝色藻类", "盐是蓝色的", "水分子会吸收阳光里的红光，剩下蓝光被散射回来，所以越深的水越蓝。纯净的水本身就是淡淡的蓝色。");
add("理科", 4, "GPS卫星上的时钟，为什么必须做相对论修正？", "钟每天快几十微秒", "钟走得太慢", "为了省电", "根本不需要修正", "卫星飞得快（钟变慢）又离地球远（引力弱钟变快），综合下来每天快约38微秒。不修正的话，定位每天会漂移十几公里。");
add("理科", 4, "布朗运动（花粉在水中乱跳）证明了什么？", "分子的存在和热运动", "水有浮力", "花粉有生命", "光有压力", "花粉被水分子从四面八方随机撞击，才跳起了“布朗舞”。爱因斯坦1905年从数学上解释了它，成为分子真实存在的有力证据。");
add("理科", 4, "微波炉加热食物，靠的是什么原理？", "微波让水分子高速振动生热", "红外线烤熟", "超声波震碎", "电阻丝加热空气", "微波炉发射的微波让食物里的水分子每秒振动几十亿次，分子摩擦就生热了。所以干巴巴没水分的东西，微波炉热不起来。");

