add("通识", 1, "火箭能飞上天，主要是利用了哪个原理？", "反冲原理", "磁铁相吸", "水的浮力", "风力发电", "火箭向下高速喷出燃气，燃气反过来把火箭向上推，这就是“作用力与反作用力”，和捏住气球口一松手、气球乱飞是一个道理。");
add("通识", 1, "宇航员在空间站里，水会变成什么形状飘着？", "水球", "水柱", "水饼", "雾气", "太空中失重，水表面的张力会把它“捏”成一个圆圆的水球。宇航员喝水时，直接从飘着的水球上“咬”一口，可好玩了。");
add("通识", 1, "微波炉加热食物，主要加热的是食物里的什么？", "水分子", "蛋白质", "维生素", "空气", "微波让食物里的水分子高速振动、摩擦生热。所以含水多的菜热得快，干馒头热得慢，空盘子放进去基本不热。");
add("通识", 1, "夏天从冰箱里拿出的冰棍冒“白气”，那白气其实是什么？", "小水滴", "二氧化碳", "氧气", "冰块碎屑", "白气是空气中的水蒸气遇到冷，凝成的无数小水滴，和冬天呵气成雾一个道理。它不是烟，凑近看会消失。");
add("通识", 1, "彩虹通常出现在太阳的哪一边？", "背对太阳的一边", "正对太阳的一边", "头顶正上方", "太阳的旁边", "彩虹是阳光射进雨滴、反射进人眼形成的，所以必须背对太阳才能看到。想看彩虹，记住：太阳在身后，雨在眼前。");
add("通识", 1, "鸟儿能在天上飞，翅膀主要靠什么“托”住身体？", "空气的升力", "羽毛的浮力", "风的推力", "翅膀的弹性", "翅膀上面弯、下面平，空气流过时下方压力大，就把鸟“托”起来了。飞机的机翼也是这个形状，原理一模一样。");
add("通识", 1, "手机没电自动关机后，之前定的闹钟还会响吗？", "不会响", "会正常响", "只振动不响", "看手机品牌", "关机后系统停止运行，闹钟程序也没法工作。所以重要考试前一晚，一定要保证手机有电，别把起床押在没电的手机上。");
add("通识", 1, "指南针上涂成红色的一端，一般指向哪个方向？", "北方", "南方", "东方", "西方", "地球本身是个大磁铁，指南针的红色端会被吸向地磁北极，也就是地理北方附近。野外迷路时它可是救命的工具。");
add("通识", 1, "冬天窗户上结的“冰花”，通常长在玻璃的哪一面？", "屋里的一面", "屋外的一面", "里外两面都有", "玻璃的夹层里", "屋里又暖又湿，暖湿空气碰到冰冷的玻璃，水汽直接凝成冰晶，所以冰花长在屋里那一面。屋外太干太冷，反而结不出来。");
add("通识", 1, "煮饺子时，怎么判断饺子熟了？", "浮上水面", "沉在锅底不动", "粘在锅沿上", "裂开两半", "饺子馅里的肉熟了会收缩，饺子皮吸水变软，整个饺子密度变小就浮起来了。所以老话说“浮起来的饺子就是熟了”。");
add("通识", 1, "雷雨天总是先看到闪电、后听到雷声，是因为什么？", "光比声音跑得快", "雷声被云挡住了", "耳朵反应比较慢", "闪电离得更近", "光每秒跑30万公里，声音每秒才跑340米。闪电的光几乎瞬间就到，雷声要慢慢“走”过来，所以总迟到。");
add("通识", 1, "骆驼的驼峰里主要储存的是什么？", "脂肪", "清水", "沙子", "空气", "很多人以为驼峰里是水，其实是脂肪。脂肪氧化能产生水和能量，骆驼就靠这两个“肉包”在沙漠里长途跋涉。");
add("通识", 1, "切洋葱时辣眼睛流泪，主要是因为洋葱释放了什么？", "刺激性气体", "洋葱的汁水", "洋葱的香气", "洋葱的绒毛", "切开洋葱会释放含硫的刺激性气体，飘进眼睛就流泪。把洋葱放冰箱冻一会儿再切，或者开着抽油烟机切，能好很多。");
add("通识", 1, "企鹅不会飞，但它属于哪一类动物？", "鸟类", "鱼类", "哺乳动物", "两栖动物", "企鹅有羽毛、会下蛋、用肺呼吸，完全符合鸟类的定义，只是翅膀变成了“鳍”，专门用来在水里“飞”。");
add("通识", 1, "蜜蜂跳“8字舞”，是在告诉同伴什么？", "哪里有花蜜", "警告有危险", "通知该回家了", "选举新蜂王", "蜜蜂用舞蹈的角度和摆动的节奏，告诉同伴花蜜的方向和距离，是昆虫界的“导航播报”，达尔文都惊叹过。");
add("通识", 2, "2024年，嫦娥六号完成了人类历史上的什么首次？", "从月球背面采样返回", "首次载人登月", "发射空间站核心舱", "登陆火星", "2024年6月，嫦娥六号从月球背面带回约1935克月壤，是人类第一次拿到月背的土。月背终年背对地球，通信得靠鹊桥中继星帮忙。");
add("通识", 2, "2021年发射的韦伯太空望远镜，主要观测哪个波段的光？", "红外线", "X射线", "伽马射线", "无线电波", "韦伯主攻红外波段，能穿透宇宙尘埃，看到138亿年前的第一代星系。它的镜面镀了一层金，在红外波段闪着金光。");
add("通识", 2, "常说的“碳中和”，这里的“碳”主要指什么？", "二氧化碳", "煤炭", "碳纤维", "石墨", "碳中和指二氧化碳的排放和吸收相抵消，排放多少就吸收多少。中国提出力争2060年前实现碳中和，种树、光伏都是帮忙的办法。");
add("通识", 2, "太阳能光伏板发电，是把什么能直接变成了电能？", "光能", "风能", "热能", "潮汐能", "太阳能电池吸收光子后释放电子，直接把光能变成电能，连中间“烧开水”的步骤都省了。阴天也能发电，只是弱一些。");
add("通识", 2, "和4G相比，5G最大的优势是什么？", "网速更快、延迟更低", "手机更便宜", "信号能穿墙", "不用建基站", "5G峰值速率可达4G的几十倍，延迟能低到1毫秒。无人驾驶、远程手术这些“等不起”的应用，全靠它撑着。");
add("通识", 2, "屠呦呦获得2015年诺贝尔生理学或医学奖，是因为发现了什么？", "发现青蒿素", "发明杂交水稻", "发现胰岛素", "研制出青霉素", "屠呦呦从黄花蒿中提取出青蒿素，治愈了无数疟疾患者。她是首位获得诺贝尔科学奖项的中国本土科学家。");
add("通识", 2, "垃圾分类时，用完的废旧电池一般属于哪一类？", "有害垃圾", "可回收物", "厨余垃圾", "其他垃圾", "电池里有汞、镉等重金属，随意丢弃会污染土壤和地下水，所以归为有害垃圾，要投进专门的红色回收箱。");
add("通识", 2, "国际空间站约90分钟绕地球一圈，宇航员一天能看到几次日出？", "16次", "1次", "8次", "32次", "90分钟一圈，一天24小时大约绕16圈，每圈经历一次日出日落。所以空间站里的一天，能看16次日出，作息全靠灯光调节。");
add("通识", 2, "物理学里说的“量子”，大致是什么意思？", "能量等物理量的最小单位", "一种高速粒子", "一种新能源", "比原子更小的灰尘", "量子不是某种具体的东西，而是“一份一份”的意思。光、能量在微观世界里都是一份一份、不连续的，这一份就叫一个量子。");
add("通识", 2, "电脑死机后，“重启试试”常常真管用，主要是因为什么？", "清空了内存里的错误状态", "硬盘被自动整理了", "CPU速度变快了", "散热风扇转起来了", "很多死机是程序把内存搞乱了，重启等于把内存清空、一切重来。所以IT支持的第一句话永远是：你重启过了吗？");
add("通识", 2, "北斗卫星导航系统是哪个国家自主建设的？", "中国", "美国", "俄罗斯", "欧盟", "北斗是中国自主建设的全球卫星导航系统，2020年完成组网。它和美国的GPS、俄罗斯的格洛纳斯、欧盟的伽利略并列为全球四大导航系统。");
add("通识", 2, "常说的“白色污染”，主要指哪种污染？", "塑料垃圾污染", "粉笔灰污染", "云层异常变白", "墙面涂料脱落", "难降解的塑料袋、一次性餐具堆积成灾，就叫白色污染。出门自带购物袋、少点一份外卖，就是在给地球减负。");
add("通识", 2, "人类历史上第一张黑洞照片，是在哪一年拍到的？", "2019年", "2008年", "2015年", "2023年", "2019年4月，“事件视界望远镜”拍到了M87星系中心黑洞那张“甜甜圈”照片。它其实拍的是黑洞阴影，爱因斯坦的预言又对了一次。");
add("通识", 2, "手机上的“蓝牙”技术，名字来源于哪位历史人物？", "一位维京国王", "一位希腊数学家", "一位美国总统", "一位英国海盗", "蓝牙得名于10世纪统一丹麦的维京国王“蓝牙哈拉尔”，连LOGO都是他名字首字母的组合，寓意像国王统一部落一样统一各种设备。");
add("通识", 2, "太阳每时每刻释放巨大能量，主要靠什么反应？", "核聚变", "化学燃烧", "核裂变", "潮汐摩擦", "太阳中心每秒把约6亿吨氢聚变成氦，释放巨大能量。人类想复制的就是“人造太阳”——可控核聚变，燃料几乎取之不尽。");
add("通识", 3, "我国的空间站叫什么名字？", "天宫", "嫦娥", "玉兔", "鹊桥", "中国空间站叫“天宫”，T字构型，由天和核心舱加问天、梦天两个实验舱组成，2022年底全面建成，可以长期住3到6名航天员。");
add("通识", 3, "“摩尔定律”说的是什么？", "芯片上晶体管数量约每两年翻一倍", "物质的量守恒", "电脑价格每年减半", "网速每年翻一番", "英特尔创始人戈登·摩尔1965年提出：芯片上的晶体管数量约每两年翻一倍。这条定律驱动了半个世纪的信息革命，如今已接近物理极限。");
add("通识", 3, "核电站发电，不管前面多高科技，最后一步本质上都是在做什么？", "烧开水推动汽轮机", "点燃内燃机", "驱动电动机", "发射火箭", "核能、火电甚至部分太阳能热发电，最后一步常常都是“烧开水→蒸汽推动汽轮机→带动发电机”。网友调侃：人类科技的尽头是烧开水。");
add("通识", 3, "2015年诺贝尔物理学奖颁给“中微子振荡”的发现，它证明了中微子有什么性质？", "有静止质量", "速度超过光速", "带有负电荷", "可以用肉眼看见", "中微子振荡现象证明中微子具有静止质量，而此前一直以为它没有质量。日本梶田隆章和加拿大麦克唐纳因此获奖。");
add("通识", 3, "“图灵测试”是用来判断什么的？", "机器是否具有智能", "电脑有没有病毒", "密码强度够不够", "网速快不快", "图灵1950年提出：如果一个人分不清和自己聊天的是人还是机器，就可以认为机器具有智能。这是人工智能领域最经典的思想实验。");
add("通识", 3, "被称为“新材料之王”的石墨烯，本质上是什么？", "单层排列的碳原子", "一种塑料", "一种金属合金", "纳米机器人", "石墨烯是单层排列的碳原子，强度是钢的200倍，导电性极好。2010年，科学家因石墨烯研究获得诺贝尔物理学奖。");
add("通识", 3, "我国“人造太阳”EAST装置创造世界纪录，突破的是哪种技术？", "可控核聚变", "太阳能电池", "氢弹小型化", "地热发电", "EAST是全超导托卡马克装置，目标是可控核聚变。它曾实现上亿摄氏度高温的长时间约束，朝“点亮”聚变堆又迈进一步。");
add("通识", 3, "GPS定位时，至少需要同时接收几颗卫星的信号？", "4颗", "2颗", "3颗", "6颗", "三颗卫星定出二维位置，第四颗用来校准接收机时钟误差，所以GPS至少要“看到”4颗卫星，楼群密集处信号差就是这个原因。");
add("通识", 3, "现代元素周期表里的元素，是按什么排序的？", "原子序数递增", "原子质量大小", "发现年代早晚", "名称首字母", "现代周期表按质子数（原子序数）递增排列。有趣的是，门捷列夫当年按原子量排，居然也大差不差，还成功预言了几种未知元素。");
add("通识", 3, "第一台通用电子计算机ENIAC诞生在哪一年？", "1946年", "1936年", "1956年", "1966年", "1946年，美国宾夕法尼亚大学诞生了ENIAC，占地170平方米、重30吨，算一道乘法都要几秒钟。和今天手机里的芯片比，它像个史前巨兽。");
add("通识", 3, "目前全球海水淡化最常用的技术是什么？", "反渗透膜过滤", "煮沸蒸馏", "加明矾沉淀", "太阳暴晒", "反渗透是用高压把海水“压”过一张只透水、不透盐的膜，全球海水淡化工程一大半靠它。中东很多国家的饮用水就是这么来的。");
add("通识", 3, "2022年诺贝尔物理学奖颁给量子纠缠实验，爱因斯坦当年把纠缠称为什么？", "鬼魅般的超距作用", "上帝掷骰子", "时空的褶皱", "宇宙的微笑", "爱因斯坦不相信纠缠，称它为“鬼魅般的超距作用”。2022年，三位科学家的实验最终为量子纠缠盖棺定论，他们也因此获奖。");
add("通识", 3, "锂成为电池主角，关键优点是什么？", "最轻的金属且化学性质活泼", "颜色好看", "产量最大", "绝对安全", "锂是最轻的金属，同样重量能存更多电，化学性质又活泼，适合做电池。2019年诺贝尔化学奖就颁给了锂离子电池的发明者。");
add("通识", 3, "“人类基因组计划”测出的基因组，本质上是什么？", "30亿个碱基对的排列顺序", "蛋白质清单", "细胞总数", "染色体照片", "人类基因组约有30亿个碱基对，2003年完成测序，相当于读完了人体的“说明书”。这项工程开启了基因检测和精准医疗时代。");
add("通识", 3, "电影《奥本海默》里造出的原子弹，原理是什么？", "核裂变", "核聚变", "化学爆炸", "反物质湮灭", "原子弹是重原子核裂变成轻原子核时释放巨大能量，和核电站同源，只是反应速度失控得多。氢弹用的才是核聚变，威力更大。");
add("通识", 4, "困扰数学界358年的费马大定理，是被谁在1994年证明的？", "怀尔斯", "高斯", "欧拉", "图灵", "英国数学家怀尔斯独自攻关七年，1994年补上证明中的漏洞，了结了这道1637年提出的难题，堪称20世纪最传奇的数学故事。");
add("通识", 4, "高度100公里的“卡门线”，被认为是什么的边界？", "大气层与太空", "地壳与地幔", "平流层与对流层", "银河系与河外星系", "卡门线是国际公认的太空起点，越过它才算真正“上过太空”。不少商业太空游的宣传，玩的就是这条线的概念。");
add("通识", 4, "2012年发现的“上帝粒子”，学名叫什么？", "希格斯玻色子", "光子", "胶子", "引力子", "希格斯玻色子赋予基本粒子质量，是标准模型的最后一块拼图。2012年欧洲核子中心宣布发现，2013年相关科学家获诺贝尔物理学奖。");
add("通识", 4, "“图灵奖”被称为什么领域的最高奖？", "计算机科学", "数学", "经济学", "和平事业", "图灵奖是计算机界的最高荣誉，奖金如今超过百万美元，奖励对计算领域做出持久贡献的人，地位相当于计算机界的诺贝尔奖。");
add("通识", 4, "悬赏百万美元、160多年无人证明的黎曼猜想，研究的是什么的分布？", "素数", "黑洞", "星系", "病毒变异", "黎曼猜想关于素数的分布规律，是数学界“皇冠上的明珠”之一。它和现代密码学息息相关，一旦被证明或证伪，影响巨大。");
add("通识", 4, "科幻里常说的“戴森球”是什么概念？", "包裹恒星收集能量的巨型结构", "一种篮球战术", "新型吸尘器品牌", "空间站的名字", "物理学家戴森设想：用巨型结构把恒星包起来，截获它全部的能量。这是II型文明的标志，在《三体》等科幻作品里都是常客。");
add("通识", 4, "比特币“挖矿”，本质上是在算什么？", "暴力穷举哈希值", "破解银行密码", "渲染3D图形", "训练AI模型", "挖矿是比谁先算出符合条件的哈希值，拼的是算力，所以矿场电费惊人。中本聪用这套机制，在没有中心机构的情况下维持了账本可信。");
add("通识", 4, "“超导”现象最初是在什么条件下被发现的？", "接近绝对零度（零下269摄氏度）", "零下50摄氏度", "常温常压", "100摄氏度以上", "1911年，昂内斯把汞冷却到零下269摄氏度，发现电阻突然消失。如今的超导磁悬浮列车、量子计算机，都建立在这项发现之上。");
add("通识", 4, "“庞加莱猜想”是由哪位数学家证明的？", "佩雷尔曼", "丘成桐", "纳什", "陶哲轩", "俄罗斯数学家佩雷尔曼2003年给出证明，却拒绝了菲尔兹奖和百万美元奖金，隐居回圣彼得堡过起了深居简出的生活。");
add("通识", 4, "哈勃发现“星系越远、退行越快”，这说明宇宙在做什么？", "膨胀", "收缩", "静止", "振荡", "哈勃定律表明宇宙在膨胀，由此倒推回去，约138亿年前宇宙诞生于一次大爆炸。这是现代宇宙学的基石之一。");
add("通识", 4, "“香农”被尊为之父的是哪门理论？", "信息论", "相对论", "博弈论", "控制论", "香农1948年创立信息论，提出了“比特”的概念。今天的手机通信、数据压缩、二维码，根子上都源于他的理论。");
add("通识", 4, "“拉格朗日点”是什么？", "引力平衡的特殊位置", "月球上的环形山", "土星光环的缝隙", "太阳黑子群", "拉格朗日点是引力和离心力平衡的特殊位置，航天器停在那里又稳又省燃料。韦伯望远镜就停在日地L2点上。");
add("通识", 4, "mRNA新冠疫苗的核心原理是什么？", "让人体细胞自己制造病毒的片段蛋白", "注射灭活病毒", "直接注射抗体", "用抗生素杀病毒", "mRNA像一张“图纸”送进细胞，细胞照着做出病毒的刺突蛋白，免疫系统记住它，真病毒来了就能打。2023年诺贝尔生理学或医学奖颁给了这项技术。");
add("通识", 4, "“暗物质”之所以“暗”，是因为什么？", "不发光也不反射电磁波", "它藏在黑洞里", "离我们太远", "被星云挡住", "暗物质不参与电磁相互作用，既不发光也不反光，只能靠引力“感觉”到它。它约占宇宙质能的27%，至今没人直接抓到过。");
add("通识", 4, "RSA加密的安全性，建立在哪道数学难题上？", "大整数质因数分解", "圆周率计算", "天气预报建模", "图像识别", "RSA靠“大数分解难”吃饭：把两个大素数相乘容易，倒过来分解却极难。量子计算机的Shor算法理论上能破解它，所以“后量子密码”正在路上。");

