add("二次元", 1, "《哆啦A梦》里，大雄姓什么？", "野比", "田中", "佐藤", "铃木", "大雄全名野比大雄，哆啦A梦正是从22世纪穿越回来帮助他的。顺带一提，哆啦A梦怕老鼠，是因为耳朵被老鼠咬掉了。");
add("二次元", 1, "《精灵宝可梦》里，皮卡丘进化之后叫什么？", "雷丘", "雷伊布", "电击兽", "伦琴猫", "皮卡丘用雷之石可以进化成雷丘，尾巴变长、耳朵变圆。在阿罗拉地区，雷丘还有超能力加电属性的地区形态，会踩着尾巴冲浪。");
add("二次元", 1, "《名侦探柯南》里，毛利小五郎被大家称为什么？", "沉睡的小五郎", "沉睡的名侦探", "日本的福尔摩斯", "毛利侦探事务所", "柯南用麻醉针让毛利小五郎睡着，再用变声器替他推理，于是有了沉睡的小五郎的名号。其实破案的全是柯南，小五郎自己完全不知情。");
add("二次元", 1, "《龙珠》里，集齐几颗龙珠可以召唤神龙？", "7颗", "5颗", "6颗", "9颗", "集齐7颗龙珠就能召唤神龙许愿。龙珠散落在世界各地，布尔玛发明的龙珠雷达就是用来找它们的，整个故事也是从找龙珠开始的。");
